import{_ as a,a0 as r,w as l,s as i,ao as d,I as n,x as t,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"10个重要的Linux ps命令实战 | LCTT x X-CMD","titleTemplate":false,"description":"10个重要的Linux ps命令实战 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10个重要的Linux ps命令实战 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10个重要的Linux ps命令实战 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141124 Important 10 Linux ps command Practical Examples","title":"10个重要的Linux ps命令实战","tag":"201501","desc":""},"relativePath":"201501/20141124 Important 10 Linux ps command Practical Examples.md","filePath":"[post].md"}'),c={name:"201501/20141124 Important 10 Linux ps command Practical Examples.md"};function g(m,p,u,h,x,_){const o=r("Link");return l(),i("div",null,[p[13]||(p[13]=d(`<h1 id="_10个重要的linux-ps命令实战" tabindex="-1">10个重要的Linux ps命令实战 <a class="header-anchor" href="#_10个重要的linux-ps命令实战" aria-label="Permalink to “10个重要的Linux ps命令实战”">​</a></h1><p>Linux作为Unix的衍生操作系统，Linux内建有查看当前进程的工具。这个工具能在命令行中使用。</p><h3 id="ps-命令是什么" tabindex="-1">PS 命令是什么 <a class="header-anchor" href="#ps-命令是什么" aria-label="Permalink to “PS 命令是什么”">​</a></h3><p>查看它的man手册可以看到，ps命令能够给出当前系统中进程的快照。它能捕获系统在某一事件的进程状态。如果你想不断更新查看的这个状态，可以使用top命令。</p><p>ps命令支持三种使用的语法格式</p><ol><li>UNIX 风格，选项可以组合在一起，并且选项前必须有“-”连字符</li><li>BSD 风格，选项可以组合在一起，但是选项前不能有“-”连字符</li><li>GNU 风格的长选项，选项前有两个“-”连字符</li></ol><p>我们能够混用这几种风格，但是可能会发生冲突。本文使用 UNIX 风格的ps命令。这里有在日常生活中使用较多的ps命令的例子。</p><h3 id="_1-不加参数执行ps命令" tabindex="-1">1. 不加参数执行ps命令 <a class="header-anchor" href="#_1-不加参数执行ps命令" aria-label="Permalink to “1. 不加参数执行ps命令”">​</a></h3><p>这是一个基本的 <strong>ps</strong> 使用。在控制台中执行这个命令并查看结果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_no_options.png" alt="不加选项执行ps命令"></p><p>结果默认会显示4列信息。</p><ul><li>PID: 运行着的命令(CMD)的进程编号</li><li>TTY: 命令所运行的位置（终端）</li><li>TIME: 运行着的该命令所占用的CPU处理时间</li><li>CMD: 该进程所运行的命令</li></ul><p>这些信息在显示时未排序。</p><h3 id="_2-显示所有当前进程" tabindex="-1">2. 显示所有当前进程 <a class="header-anchor" href="#_2-显示所有当前进程" aria-label="Permalink to “2. 显示所有当前进程”">​</a></h3><p>使用 <strong>-a</strong> 参数。<strong>-a 代表 all</strong>。同时加上x参数会显示没有控制终端的进程。</p><pre><code>$ ps -ax
</code></pre><p>这个命令的结果或许会很长。为了便于查看，可以结合less命令和管道来使用。</p><pre><code>$ ps -ax | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_ax.png" alt="ps all 信息"></p><h3 id="_3-根据用户过滤进程" tabindex="-1">3. 根据用户过滤进程 <a class="header-anchor" href="#_3-根据用户过滤进程" aria-label="Permalink to “3. 根据用户过滤进程”">​</a></h3><p>在需要查看特定用户进程的情况下，我们可以使用 <strong>-u</strong> 参数。比如我们要查看用户&#39;pungki&#39;的进程，可以通过下面的命令：</p><pre><code>$ ps -u pungki
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps__u.png" alt="通过用户过滤"></p><h3 id="_4-通过cpu和内存使用来过滤进程" tabindex="-1">4. 通过cpu和内存使用来过滤进程 <a class="header-anchor" href="#_4-通过cpu和内存使用来过滤进程" aria-label="Permalink to “4. 通过cpu和内存使用来过滤进程”">​</a></h3><p>也许你希望把结果按照 CPU 或者内存用量来筛选，这样你就找到哪个进程占用了你的资源。要做到这一点，我们可以使用 <strong>aux 参数</strong>，来显示全面的信息:</p><pre><code>$ ps -aux | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_aux.png" alt="显示全面信息"></p><p>当结果很长时，我们可以使用管道和less命令来筛选。</p><p>默认的结果集是未排好序的。可以通过 <strong>--sort</strong>命令来排序。</p><p>根据 <strong>CPU 使用</strong>来升序排序</p><pre><code>$ ps -aux --sort -pcpu | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_aux_sort_cpu.png" alt="根据cpu使用排序"></p><p>根据 <strong>内存使用</strong> 来升序排序</p><pre><code>$ ps -aux --sort -pmem | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_aux_sort_mem.png" alt="根据内存使用来排序"></p><p>我们也可以将它们合并到一个命令，并通过管道显示前10个结果：</p><pre><code>$ ps -aux --sort -pcpu,+pmem | head -n 10
</code></pre><h3 id="_5-通过进程名和pid过滤" tabindex="-1">5. 通过进程名和PID过滤 <a class="header-anchor" href="#_5-通过进程名和pid过滤" aria-label="Permalink to “5. 通过进程名和PID过滤”">​</a></h3><p>使用 <strong>-C 参数</strong>，后面跟你要找的进程的名字。比如想显示一个名为getty的进程的信息，就可以使用下面的命令：</p><pre><code>$ ps -C getty
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_C.png" alt="通过进程名和PID过滤"></p><p>如果想要看到更多的细节，我们可以使用-f参数来查看格式化的信息列表：</p><pre><code>$ ps -f -C getty
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_C_f.png" alt="通过进程名和PID过滤"></p><h3 id="_6-根据线程来过滤进程" tabindex="-1">6. 根据线程来过滤进程 <a class="header-anchor" href="#_6-根据线程来过滤进程" aria-label="Permalink to “6. 根据线程来过滤进程”">​</a></h3><p>如果我们想知道特定进程的线程，可以使用<strong>-L 参数</strong>，后面加上特定的PID。</p><pre><code>$ ps -L 1213
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_L.png" alt="根据线程来过滤进程"></p><h3 id="_7-树形显示进程" tabindex="-1">7. 树形显示进程 <a class="header-anchor" href="#_7-树形显示进程" aria-label="Permalink to “7. 树形显示进程”">​</a></h3><p>有时候我们希望以树形结构显示进程，可以使用 <strong>-axjf</strong> 参数。</p><pre><code>$ps -axjf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_axjf.png" alt="树形显示进程"></p><p>或者可以使用另一个命令。</p><pre><code>$ pstree
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/pstree.png" alt="树形显示进程"></p><h3 id="_8-显示安全信息" tabindex="-1">8. 显示安全信息 <a class="header-anchor" href="#_8-显示安全信息" aria-label="Permalink to “8. 显示安全信息”">​</a></h3><p>如果想要查看现在有谁登入了你的服务器。可以使用ps命令加上相关参数:</p><pre><code>$ ps -eo pid,user,args
</code></pre><p><strong>参数 -e</strong> 显示所有进程信息，<strong>-o 参数</strong>控制输出。<strong>Pid</strong>,<strong>User 和 Args</strong>参数显示<strong>PID，运行应用的用户</strong>和<strong>该应用</strong>。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_security_1.png" alt="显示安全信息"></p><p>能够与<strong>-e 参数</strong> 一起使用的关键字是<strong>args, cmd, comm, command, fname, ucmd, ucomm, lstart, bsdstart 和 start</strong>。</p><h3 id="_9-格式化输出root用户-真实的或有效的uid-创建的进程" tabindex="-1">9. 格式化输出root用户（真实的或有效的UID）创建的进程 <a class="header-anchor" href="#_9-格式化输出root用户-真实的或有效的uid-创建的进程" aria-label="Permalink to “9. 格式化输出root用户（真实的或有效的UID）创建的进程”">​</a></h3><p>系统管理员想要查看由root用户运行的进程和这个进程的其他相关信息时，可以通过下面的命令:</p><pre><code>$ ps -U root -u root u
</code></pre><p><strong>-U 参数</strong>按真实用户ID(RUID)筛选进程，它会从用户列表中选择真实用户名或 ID。真实用户即实际创建该进程的用户。</p><p><strong>-u</strong> 参数用来筛选有效用户ID（EUID）。</p><p>最后的<strong>u</strong>参数用来决定以针对用户的格式输出，由<strong>User, PID, %CPU, %MEM, VSZ, RSS, TTY, STAT, START, TIME 和 COMMAND</strong>这几列组成。</p><p>这里有上面的命令的输出结果：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_root_real_effective_ID.png" alt="show real and effective User ID"></p><h3 id="_10-使用ps实时监控进程状态" tabindex="-1">10. 使用PS实时监控进程状态 <a class="header-anchor" href="#_10-使用ps实时监控进程状态" aria-label="Permalink to “10. 使用PS实时监控进程状态”">​</a></h3><p>ps 命令会显示你系统当前的进程状态，但是这个结果是静态的。</p><p>当有一种情况，我们需要像上面第四点中提到的通过CPU和内存的使用率来筛选进程，并且我们希望结果能够每秒刷新一次。为此，我们可以<strong>将ps命令和watch命令结合起来</strong>。</p><pre><code>$ watch -n 1 ‘ps -aux --sort -pmem, -pcpu’
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_watch_1.png" alt="组合 ps 和 watch"></p><p>如果输出太长，我们也可以限制它，比如前20条，我们可以使用<strong>head</strong>命令来做到。</p><pre><code>$ watch -n 1 ‘ps -aux --sort -pmem, -pcpu | head 20’
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_watch_2.png" alt="组合 ps 和 watch"></p><p>这里的动态查看并不像top或者htop命令一样。<strong>但是使用ps的好处是</strong>你能够定义显示的字段，你能够选择你想查看的字段。</p><p>举个例子，<strong>如果你只需要看名为&#39;pungki&#39;用户的信息</strong>，你可以使用下面的命令：</p><pre><code>$ watch -n 1 ‘ps -aux -U pungki u --sort -pmem, -pcpu | head 20’
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_watch_3.png" alt="组合 ps 和 watch"></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>你也许每天都会使用ps命令来监控你的Linux系统。但是事实上，你可以通过ps命令的参数来生成各种你需要的报表。</p><p>ps命令的另一个优势是ps是各种 Linux系统都默认安装的，因此你只要用就行了。</p><p>不要忘了通过 man ps来查看更多的参数。（LCTT 译注：由于 ps 命令古老而重要，所以它在不同的 UNIX、BSD、Linux 等系统中的参数不尽相同，因此如果你用的不是 Linux 系统，请查阅你的文档了解具体可用的参数。）</p><hr>`,86)),n("p",null,[p[1]||(p[1]=t("via: ",-1)),e(o,{href:"http://linoxide.com/how-tos/linux-ps-command-examples/"},{default:s(()=>[...p[0]||(p[0]=[t("http://linoxide.com/how-tos/linux-ps-command-examples/",-1)])]),_:1})]),n("p",null,[p[5]||(p[5]=t("作者：",-1)),e(o,{href:"http://linoxide.com/author/pungki/"},{default:s(()=>[...p[2]||(p[2]=[t("Pungki Arianto",-1)])]),_:1}),p[6]||(p[6]=t(" 译者：",-1)),e(o,{href:"https://github.com/johnhoow"},{default:s(()=>[...p[3]||(p[3]=[t("johnhoow",-1)])]),_:1}),p[7]||(p[7]=t(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:s(()=>[...p[4]||(p[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[p[10]||(p[10]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...p[8]||(p[8]=[t("LCTT",-1)])]),_:1}),p[11]||(p[11]=t(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:s(()=>[...p[9]||(p[9]=[t("Linux中国",-1)])]),_:1}),p[12]||(p[12]=t(" 荣誉推出",-1))])])}const w=a(c,[["render",g]]);export{P as __pageData,w as default};
